package lt.benas.wispbound;
import android.app.*;import android.content.*;import android.content.pm.*;import android.os.Build;import android.net.Uri;import android.provider.Settings;import org.json.JSONObject;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
public final class Updater {
 static final String ORIGIN="https://palcikevicius-glitch.github.io/wispbound/dist";static final long MAX=80L*1024*1024;static volatile String state="idle";static volatile boolean busy=false,permissionPending=false;static JSONObject release;static int expectedCode=0;static String expectedHash="";static long expectedSize=0;
 static synchronized boolean begin(){if(busy||state.equals("installing"))return false;busy=true;return true;}
 static void set(String value,int progress){state=value;try{MainActivity.update(new JSONObject().put("state",value).put("progress",progress).toString());}catch(Exception ignored){}}
 static HttpURLConnection connect(String path)throws Exception {HttpURLConnection c=(HttpURLConnection)new URL(ORIGIN+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(25000);c.setRequestProperty("Cache-Control","no-cache");int status=c.getResponseCode();if(status!=200){c.disconnect();throw new IOException("HTTP status");}return c;}
 static byte[] limited(InputStream in,int max)throws IOException {ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>max)throw new IOException("Too large");out.write(b,0,n);}return out.toByteArray();}
 static long code(PackageInfo p){return Build.VERSION.SDK_INT>=28?p.getLongVersionCode():p.versionCode;}
 static int flags(){return Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;}
 static Signature[] signers(PackageInfo p){return Build.VERSION.SDK_INT>=28&&p.signingInfo!=null?p.signingInfo.getApkContentsSigners():p.signatures;}
 static File file(Context c){return new File(c.getCacheDir(),"wispbound-update.apk");}
 static boolean verified(Context c,File f)throws Exception {if(!f.isFile()||f.length()!=expectedSize)return false;MessageDigest sha=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1)sha.update(b,0,n);}StringBuilder hash=new StringBuilder();for(byte b:sha.digest())hash.append(String.format(Locale.ROOT,"%02x",b&255));if(!hash.toString().equals(expectedHash))return false;PackageManager pm=c.getPackageManager();PackageInfo candidate=pm.getPackageArchiveInfo(f.getAbsolutePath(),flags()),current=pm.getPackageInfo(c.getPackageName(),flags());if(candidate==null||!c.getPackageName().equals(candidate.packageName)||code(candidate)!=expectedCode||code(candidate)<=code(current))return false;Signature[] a=signers(candidate),b=signers(current);if(a==null||b==null||a.length==0||a.length!=b.length)return false;for(Signature sig:a)if(!Arrays.asList(b).contains(sig))return false;return true;}
 static void check(Activity activity){if(!begin())return;set("checking",-1);final Context context=activity.getApplicationContext();new Thread(()->{try{HttpURLConnection c=connect("/release.json?t="+System.currentTimeMillis());JSONObject r;try(InputStream in=c.getInputStream()){r=new JSONObject(new String(limited(in,32768),StandardCharsets.UTF_8));}finally{c.disconnect();}int build=r.getInt("build");if(r.getInt("schema")!=1||build<1||!r.getString("version").matches("(?:[0-9]+\\.[0-9]{2}|[0-9]+\\.[0-9]+\\.[0-9]+)"))throw new IOException("Bad manifest");if(build<=code(context.getPackageManager().getPackageInfo(context.getPackageName(),0))){release=r;set("current",-1);return;}if(!r.getString("channel").equals("direct")&&!r.getString("channel").equals("store"))throw new IOException("Bad channel");if(r.getString("channel").equals("direct")){JSONObject a=r.getJSONObject("android");expectedCode=build;expectedHash=a.getString("sha256");expectedSize=a.getLong("size");if(!a.getString("package").equals(context.getPackageName())||!expectedHash.matches("[a-f0-9]{64}")||expectedSize<1||expectedSize>MAX)throw new IOException("Bad release");}release=r;set("available",-1);}catch(Exception e){set("failed",-1);}finally{busy=false;}},"wispbound-check").start();}
 static void download(Activity activity){if(activity instanceof MainActivity&&((MainActivity)activity).runActive){set("active",-1);return;}if(release==null){check(activity);return;}if("store".equals(release.optString("channel"))){try{Uri uri=Uri.parse(release.getString("playUrl"));if(!"https".equals(uri.getScheme())||!"play.google.com".equals(uri.getHost()))throw new IOException("Bad store");activity.runOnUiThread(()->activity.startActivity(new Intent(Intent.ACTION_VIEW,uri)));}catch(Exception e){set("failed",-1);}return;}if(!begin())return;set("downloading",0);final Context context=activity.getApplicationContext();new Thread(()->{File partial=new File(context.getCacheDir(),"wispbound-update.partial");try{if(verified(context,file(context))){set("ready",100);return;}HttpURLConnection c=connect("/wispbound-android.apk?t="+expectedCode);long size=c.getContentLengthLong();if(size>MAX){c.disconnect();throw new IOException("Too large");}try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(partial)){byte[] b=new byte[32768];int n,last=-1;long total=0;while((n=in.read(b))!=-1){total+=n;if(total>expectedSize||total>MAX)throw new IOException("Too large");out.write(b,0,n);int p=(int)(total*100/expectedSize);if(p!=last){last=p;set("downloading",p);}}if(total!=expectedSize)throw new IOException("Incomplete");}finally{c.disconnect();}set("verifying",100);if(!verified(context,partial))throw new IOException("Verification failed");File dest=file(context);if(dest.exists()&&!dest.delete())throw new IOException("Cache busy");if(!partial.renameTo(dest))throw new IOException("Cache failure");set("ready",100);}catch(Exception e){set("failed",-1);}finally{partial.delete();busy=false;}},"wispbound-download").start();}
 static void install(Activity activity){if(activity instanceof MainActivity&&((MainActivity)activity).runActive){set("active",-1);return;}if(!state.equals("ready")&&!state.equals("cancelled"))return;if(!activity.getPackageManager().canRequestPackageInstalls()){permissionPending=true;set("permission",-1);try{activity.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName())));}catch(Exception e){permissionPending=false;set("ready",-1);}return;}if(!begin())return;set("installing",-1);final Context context=activity.getApplicationContext();new Thread(()->{PackageInstaller.Session session=null;try{File apk=file(context);if(!verified(context,apk))throw new IOException("Unverified");PackageInstaller installer=context.getPackageManager().getPackageInstaller();PackageInstaller.SessionParams p=new PackageInstaller.SessionParams(PackageInstaller.SessionParams.MODE_FULL_INSTALL);p.setAppPackageName(context.getPackageName());p.setSize(apk.length());if(Build.VERSION.SDK_INT>=31)p.setRequireUserAction(PackageInstaller.SessionParams.USER_ACTION_REQUIRED);int id=installer.createSession(p);session=installer.openSession(id);try(InputStream in=new FileInputStream(apk);OutputStream out=session.openWrite("base.apk",0,apk.length())){byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1)out.write(b,0,n);session.fsync(out);}Intent callback=new Intent(context,InstallReceiver.class).setAction("lt.benas.wispbound.UPDATE_STATUS");int f=PendingIntent.FLAG_UPDATE_CURRENT|(Build.VERSION.SDK_INT>=31?PendingIntent.FLAG_MUTABLE:0);session.commit(PendingIntent.getBroadcast(context,19,callback,f).getIntentSender());}catch(Exception e){if(session!=null)session.abandon();set("ready",-1);}finally{busy=false;if(session!=null)session.close();}},"wispbound-install").start();}
 static void resume(Activity a){if(permissionPending){permissionPending=false;set("ready",-1);if(a.getPackageManager().canRequestPackageInstalls())install(a);}}
 public static final class InstallReceiver extends BroadcastReceiver {@Override public void onReceive(Context c,Intent i){int status=i.getIntExtra(PackageInstaller.EXTRA_STATUS,PackageInstaller.STATUS_FAILURE);if(status==PackageInstaller.STATUS_PENDING_USER_ACTION){Intent confirm=i.getParcelableExtra(Intent.EXTRA_INTENT);if(confirm!=null)try{c.startActivity(confirm.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}catch(Exception e){set("ready",-1);}}else set(status==PackageInstaller.STATUS_SUCCESS?"current":"cancelled",-1);}}
}
